with target as(select * from public.works where id=any(array[1603,3378,3400,3404,5012,5173,5799,3481]::bigint[]) or open_library_id=any(array['OL79324W','OL45813W','OL257944W','OL17356545W','OL15129290W','OL26380484W','OL37505458W','OL19336182W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['spoorloos','goneforgood','opwegnaardehemel','kisskiss','deijsdraak','theicedragon','deverbeelding','foolmeonce','deterugkeervandeleeuw','thelion','debonoboendetiengeboden','thebonoboandtheatheist','emilywildesatlasderanderlanden','emilywildesmapoftheotherlands','stadvolgeesten','cityofghosts']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['spoorloos','goneforgood','opwegnaardehemel','kisskiss','deijsdraak','theicedragon','deverbeelding','foolmeonce','deterugkeervandeleeuw','thelion','debonoboendetiengeboden','thebonoboandtheatheist','emilywildesatlasderanderlanden','emilywildesmapoftheotherlands','stadvolgeesten','cityofghosts']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL39821A','OL34184A','OL234664A','OL25714A','OL2628905A','OL3072525A','OL6979295A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['harlancoben','cobenharlan','roalddahl','roalddalh','georgerrmartin','qiaozhirrmading','georgeraymondrichardmartin','nelsondemille','bradmatthewspseud','jackcannonpseud','kurtladnerpseud','fransdewaal','fbmdewaal','fransbmdewaal','fbmdefransbmwaal','heatherfawcett','heatherheathermfawcett','heathermfawcett','fawcettheather','veschwab','victoriaelizabethschwab','victoriaschwab']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL46536248M','OL47139318M','OL27305785M','OL45814648M','OL47797174M','OL26374446M','OL60993010M','OL60567993M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789022582138','9789046130308','9789024522330','9789022565162','9789044330427','9789045030791','9789020556643','9789022599501']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
